    @Test func vectorResizingFromUInt8ThroughPair() {
        let mismatches = Mismatches(
            "vectorResizingFromUInt8 through GenericAnySourcePair<Int64, UInt8>"
        )
        let aInputs = Inputs.conversions(SIMD<UInt8>.self, seed: 0x21AD_0FD9_A73E_8985)
        for a in aInputs {
            let port = GenericAnySourcePair<Int64, UInt8>.vector(resizing: a)
            let reference = H.vector(resizing: a)
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                definedBytes
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

